struct Base {
    virtual ~Base() = default;
    virtual void f() const { std::cout << "Base\n"; }
};
struct Der : Base {
    void f() const override { std::cout << "Der\n"; }
};

int main() {
    Der d;
    Base b = d;      // slicing: b är en ren Base
    b.f();           // "Base"

    Base& r = d;     // referens: ingen kopia
    r.f();           // "Der"
}

